import{_ as e,o,c as a,a2 as r}from"./chunks/framework.CGSzHL4z.js";const p=JSON.parse('{"title":"Compared to other tools","description":"","frontmatter":{},"headers":[],"relativePath":"guide/comparison.md","filePath":"guide/comparison.md","lastUpdated":1792713747000}'),n={name:"guide/comparison.md"};function s(d,t,i,l,h,c){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="compared-to-other-tools" tabindex="-1">Compared to other tools <a class="header-anchor" href="#compared-to-other-tools" aria-label="Permalink to &quot;Compared to other tools&quot;">​</a></h1><p>The biggest difference is what happens in game. A Roblox animation plays the same joint motion wherever it runs. An AcesMotion scene is cast by role, Motion Warp fits a path to where the target really is, and constraints, drivers and generators work on the live scene. AcesMotion also works alongside Roblox animations: a scene that only moves one rig&#39;s joints exports as a native one.</p><div class="am-compare"><table tabindex="0"><thead><tr><th></th><th>AcesMotion</th><th>Roblox Animation Editor</th></tr></thead><tbody><tr><td>Lands on a target wherever it stands</td><td>Motion Warp re-fits the path in game</td><td>No, the keyed path plays as is</td></tr><tr><td>Reacts to the live scene in game</td><td>Constraints and drivers run live</td><td>No</td></tr><tr><td>Procedural motion without keys</td><td>Generators (Shake, Wiggle, Oscillate...)</td><td>No</td></tr><tr><td>Several rigs in one file</td><td>Yes, a scene of any size</td><td>No, one rig per animation</td></tr><tr><td>Animate any property (lights, VFX, colours)</td><td>Yes, with editors per type</td><td>No, joints and face only</td></tr><tr><td>Cameras</td><td>Camera actors, look-through, shot switching</td><td>No</td></tr><tr><td>Plays in a game without an upload</td><td>Yes, the runtime plays scene data</td><td>No, upload required</td></tr><tr><td>Owner-locked assets</td><td>Never with the runtime</td><td>Yes</td></tr><tr><td>Multiplayer playback built in</td><td><code>PlayForAll</code>, server clock, late joiners</td><td>Through Roblox&#39;s Animator</td></tr><tr><td>Events on an exact frame</td><td>Markers and Event blocks, on the server too</td><td>Animation events</td></tr><tr><td>Sound on the Timeline</td><td>Waveforms, trims, fades, peak snapping</td><td>No</td></tr><tr><td>Curve editor</td><td>Bezier, tangents, Ease view, presets</td><td>Yes</td></tr><tr><td>Native Roblox export</td><td>Yes, when the scene fits</td><td>It is native</td></tr><tr><td>Custom code at a frame</td><td>Custom actions with typed parameters</td><td>No</td></tr><tr><td>Price</td><td>To be announced</td><td>Free</td></tr></tbody></table></div><h2 id="when-to-use-what" tabindex="-1">When to use what <a class="header-anchor" href="#when-to-use-what" aria-label="Permalink to &quot;When to use what&quot;">​</a></h2><ul><li><strong>One rig, simple loop (idle, walk):</strong> either works. AcesMotion adds onion skin, motion trails and its curve editor, then exports natively.</li><li><strong>An attack that has to reach a target at any range:</strong> AcesMotion. Motion Warp bends the path onto the real target in game.</li><li><strong>An ability with VFX, sound and a hit frame:</strong> AcesMotion. The timing lives in one place and fires as signals in your code.</li><li><strong>A multiplayer cutscene:</strong> AcesMotion&#39;s <code>PlayForAll</code> keeps every player on the same frame.</li><li><strong>A scene you sell or share:</strong> the runtime is MIT licensed and scenes aren&#39;t owner-locked.</li></ul><h2 id="coming-from-blender-or-maya" tabindex="-1">Coming from Blender or Maya <a class="header-anchor" href="#coming-from-blender-or-maya" aria-label="Permalink to &quot;Coming from Blender or Maya&quot;">​</a></h2><p>The words you know mostly carry over: dope sheet, curve editor, tangents, onion skin, motion trails, IK, pins. The differences are Roblox ones: joints are Motor6D, AnimationConstraint or Bone, and a scene&#39;s time is stored in ticks so changing the frame rate never shifts keys. See <a href="./concepts">Concepts</a>.</p>',7)])])}const g=e(n,[["render",s]]);export{p as __pageData,g as default};
